import os,json,hashlib,subprocess,time,traceback,base64,zlib
from pathlib import Path
from datetime import datetime,timezone
root=Path("/u/scratch/r/rushil/AI_Assisted_SIDIS/polarized_SIDIS_20260917T063521Z")
os.environ.update(LC_ALL='C',LANG='C')
specs=json.loads(zlib.decompress(base64.b64decode("")).decode())
def digest(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def event(name,**kw):
    row={'event':name,'utc':datetime.now(timezone.utc).isoformat()};row.update(kw);print(json.dumps(row),flush=True)
def accepted(relative):
    path=root/relative;r=json.loads(path.read_text())
    if not r.get('passed'): raise RuntimeError('upstream execution did not pass: '+relative)
    hashes={relative:digest(path)}
    for rel,h in r['result_sha256'].items():
        if digest(root/rel)!=h: raise RuntimeError('accepted output changed: '+rel)
        hashes[rel]=h
    return r,hashes
def run():
    pred='Hgg/s08_other_group_components_result/s08_execution.json'
    predlog=root/'cache/s08_Hgg_exact_reconstruction_20260925_controller.log'
    event('WAITING_FOR_COMPLETE_MAPPING',receipt=pred)
    while True:
        if (root/pred).exists():
            r=json.loads((root/pred).read_text())
            if r.get('passed'): break
            if r.get('reason')!='wall_limit' and r.get('job_id')!='14906378': raise RuntimeError('mapping failed: '+str(r.get('job_id')))
        if predlog.exists() and '"event": "CONTROLLER_ERROR"' in predlog.read_text()[-12000:]:
            raise RuntimeError('mapping controller requires inspection')
        time.sleep(30)
    _,dependencies=accepted(pred)
    _,own=accepted('Hgg/s08_direct_group_component_result/s08_execution.json');dependencies.update(own)
    for spec in specs:
        stage=spec['stage'];j=json.loads(json.dumps(spec['job']));tag='s08_Hgg_final_chain_20260924_'+stage
        for rel,h in j['reviewed_sha256'].items():
            if digest(root/rel)!=h: raise RuntimeError('reviewed stage input changed: '+rel)
        j['reviewed_sha256'].update(dependencies)
        j['log']='cache/'+tag+'.log';j['heartbeat']='cache/'+tag+'_heartbeat.json'
        for key in ['MATHEMATICA_USERBASE','WOLFRAM_USERBASE']: j['environment'][key]='{root}/cache/wolfram_'+tag
        cfg='.cluster/'+tag+'_job.json';cp=root/cfg;sp=root/('.cluster/s08_result/'+tag+'_submission.json')
        rp=root/j['execution_result']
        if rp.exists() and not cp.exists():
            old=json.loads(rp.read_text())
            if old.get('passed'): raise RuntimeError('pre-existing accepted stage requires source/input identity review: '+stage)
            archive=root/('.cluster/s08_result/'+tag+'_prior_'+str(old.get('job_id'))+'_execution.json')
            if archive.exists(): raise RuntimeError('failed-stage provenance archive already exists')
            rp.replace(archive)
        if cp.exists():
            if json.loads(cp.read_text())!=j or not sp.exists(): raise RuntimeError('existing stage generation mismatch: '+stage)
            sub=json.loads(sp.read_text())
            if sub['configuration_sha256']!=digest(cp): raise RuntimeError('submitted configuration changed')
            jid=sub['job_id']
        else:
            cp.write_text(json.dumps(j,indent=2,sort_keys=True)+'\n')
            args=['qsub','-terse','-N','pSIDIS_'+tag,'-S','/bin/bash','-l','h_rt=04:00:00,h_data='+str(spec['memory_gib_per_slot'])+'G','-wd',str(root),'-j','y','-o',str(root/('cache/'+tag+'_scheduler.log'))]
            if spec['slots']>1: args+=['-pe','shared',str(spec['slots'])]
            script='#!/bin/bash\nset -eu\nexport LC_ALL=C LANG=C\nexec python3 '+str(root/'.cluster/s02_execute.py')+' --root '+str(root)+' --job '+cfg+'\n'
            p=subprocess.run(args,input=script,stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True)
            if p.returncode: raise RuntimeError(p.stderr)
            jid=p.stdout.strip().split('.')[0]
            sub={'job_id':jid,'stage':stage,'config':cfg,'configuration_sha256':digest(cp),'qsub':args,'script':script}
            sp.write_text(json.dumps(sub,indent=2)+'\n')
        event('STAGE_SUBMITTED',**sub)
        last=None;missing=0;lastchange=time.monotonic()
        while not rp.exists():
            p=subprocess.run(['qstat','-j',jid],stdout=subprocess.PIPE,stderr=subprocess.PIPE,universal_newlines=True,timeout=30)
            lp=root/j['log'];size=lp.stat().st_size if lp.exists() else 0
            state=(p.returncode,size)
            if state!=last:
                last=state;lastchange=time.monotonic()
                tail='\n'.join(lp.read_text(errors='replace').splitlines()[-5:])[-4000:] if size else ''
                event('NATIVE_PROGRESS',stage=stage,job_id=jid,log_bytes=size,tail=tail)
            missing=missing+1 if p.returncode else 0
            if missing>=6: raise RuntimeError('job disappeared without receipt: '+jid)
            if size and time.monotonic()-lastchange>j['limits']['inactivity_seconds']+180: raise RuntimeError('native stage stalled: '+jid)
            time.sleep(30)
        receipt=json.loads(rp.read_text())
        event('STAGE_FINISHED',stage=stage,job_id=jid,passed=receipt.get('passed'),reason=receipt.get('reason'),exit_code=receipt.get('exit_code'))
        receipt,new=accepted(j['execution_result']);dependencies.update(new)
        event('STAGE_ACCEPTED',stage=stage,job_id=jid,outputs=receipt['result_sha256'])
    event('FINAL_EXPORT_ACCEPTED',receipt='Hgg/s15_result/s15_execution.json')
try:
    run()
except Exception as exc:
    event('CONTROLLER_ERROR',error=str(exc));traceback.print_exc()
finally:
    event('CONTROLLER_EXIT')
